 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-APPS-085"
  ],
  "summary": "FAM:SF-APPS-085 directly addressed the split-half reliability of a player-season attribute (connector quality Q_p, an on-off PPP gap), finding it to be untestable as a stable trait due to very low reliability (ICC=0.216) and high within-player variance. This provides strong indirect evidence that a 'defense's effect on opponents' H2-H1 change' as a 'reliable team trait' would also be untestable. Other studies (FAM:SF-APPS-018, FAM:SF15, FAM:SF-APPS-068) highlight general challenges in measuring defensive impacts and H2 changes due to low reliability, small samples, confounding, and mechanical artifacts."
 },
 "risks": [
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The core concept of 'reliable team trait' is directly threatened by the likely low measurement reliability of 'H2-H1 change' in opponent performance, as evidenced by similar split-half measures (FAM:SF-APPS-085)."
  },
